/* =============================================================================
 * telemetryhistory.js — Telemetry History page logic.
 *
 * Ported verbatim from the web project (E7MRIV2Web)
 * Areas/FRS25/Views/TelemetryHistory/Index.cshtml inline <script>, so every
 * API call, table, graph, pager and export on this page behaves exactly as the
 * web project's. When the web page changes, re-port it here rather than
 * patching this copy by hand.
 *
 * Kept as a static file rather than inline in Index.cshtml: Razor emits each
 * markup run as one WriteLiteral that csc re-splits into chunks, and a ~1 MB
 * inline script trips CS1647 (the web view works around it with "Razor literal
 * split" comments, which are dropped here).
 *
 * Server endpoints (TelemetryHistoryController / TelemetryController):
 *   TelemetryHistory: GetUserAssetInfo, GetUserAssetInfoDatalogger,
 *     GetAssetAttributes, GetAssetTypeBySiteId, GetVibrationConfig,
 *     GetSiteByDivisionId, GetAssestBy, GetSiteById, GetHistoryData,
 *     GetHistoryDataDashboard, GetPMHistoryOperation, GetPMHistoryIntegration,
 *     GetPMHistoryVibration, GetPMHistoryOperationArray,
 *     GetFRSAttributeRangeBySiteId
 *   Telemetry: GetDivisionByZoneId, GetBulkAssetMetadata, GetGraphHistory
 * ========================================================================== */
    // ===== TOAST NOTIFICATION SYSTEM =====
    function showToast(type, title, message, duration) {
        duration = duration || 4000;
        var icons = { success: '<i class="fas fa-check"></i>', error: '<i class="fas fa-times"></i>', warning: '<i class="fas fa-exclamation-triangle"></i>', info: '<i class="fas fa-info-circle"></i>' };
        var toastId = 'toast_' + Date.now();
        var toastHtml = '<div class="toast-notification toast-' + type + '" id="' + toastId + '"><div class="toast-icon">' + icons[type] + '</div><div class="toast-body"><div class="toast-title">' + title + '</div><div class="toast-message">' + message + '</div></div><button type="button" class="toast-close" onclick="closeToast(\'' + toastId + '\')">×</button><div class="toast-progress"></div></div>';
        $('#toastContainer').append(toastHtml);
        setTimeout(function () { closeToast(toastId); }, duration);
    }

    function closeToast(toastId) {
        var $toast = $('#' + toastId);
        if ($toast.length && !$toast.hasClass('hiding')) {
            $toast.addClass('hiding');
            setTimeout(function () { $toast.remove(); }, 300);
        }
    }

    function showSuccess(message, title) { showToast('success', title || 'Success', message); }
    function showError(message, title) { showToast('error', title || 'Error', message); }
    function showWarning(message, title) { showToast('warning', title || 'Warning', message); }
    function showInfo(message, title) { showToast('info', title || 'Information', message); }


    function getHistoryReportRecords(attribute, getExistingTimestamp) {
    if (typeof getExistingTimestamp !== 'function') {
        throw new TypeError('Pass the existing report timestamp selector.');
    }

    var values = (attribute && attribute.Values) || {};

    var keys = Object.keys(values).filter(function (key) {
        return values[key] && typeof values[key] === 'object';
    });

    // Numeric sequence keys, as in your API response: 1, 2, ... 82.
    keys.sort(function (a, b) {
        return Number(a) - Number(b);
    });

    return keys.map(function (key, index) {
        var record = values[key];
        var timestamp = record.Timestamp || {};
        var isBoundary = index === 0 || index === keys.length - 1;
        var local = timestamp.TimestampLocal;

        var validLocal = typeof local === 'string' &&
            local.trim() !== '' &&
            !/^0001-01-01/.test(local.trim()) &&
            !isNaN(Date.parse(local));

        return {
            record: record,
            timestamp: isBoundary && validLocal ? local : getExistingTimestamp(record),
            isBoundary: isBoundary
        };
    });
}



