    function getIpsEldHistoryDataLoggerInfo(assetId, attrId) {
        var assetKey = String(assetId);
        var attrKey = String(attrId);

        var assetInfoList =
            (ASSET_INFO_MAP &&
                ASSET_INFO_MAP[assetKey]) || [];

        for (var i = 0; i < assetInfoList.length; i++) {
            var assetInfo = assetInfoList[i];

            if (
                !assetInfo ||
                assetInfo.RoleType !== 'd'
            ) {
                continue;
            }

            if (
                String(assetInfo.Role) === attrKey ||
                String(assetInfo.AssetAttributeId) === attrKey
            ) {
                return assetInfo;
            }
        }

        var dataloggerList =
            (DATALOGGER_ASSET_MAP &&
                DATALOGGER_ASSET_MAP[assetKey]) || [];

        for (var j = 0; j < dataloggerList.length; j++) {
            var dataloggerInfo = dataloggerList[j];

            if (!dataloggerInfo) {
                continue;
            }

            if (
                String(
                    dataloggerInfo.DataloggerAttributeId
                ) === attrKey ||
                String(dataloggerInfo.Role) === attrKey ||
                String(
                    dataloggerInfo.HistoryAttributeId
                ) === attrKey
            ) {
                return {
                    RoleType: 'd',

                    Role:
                        dataloggerInfo.Role !== undefined &&
                        dataloggerInfo.Role !== null
                            ? dataloggerInfo.Role
                            : dataloggerInfo
                                .DataloggerAttributeId,

                    AssetAttributeId:
                        dataloggerInfo.HistoryAttributeId,

                    AttributeName:
                        dataloggerInfo
                            .DataloggerAttribute || '',

                    CanonicalName:
                        dataloggerInfo
                            .DataloggerAttribute || '',

                    AliasName:
                        dataloggerInfo
                            .DataloggerAttribute || ''
                };
            }
        }

        return null;
    }




    // ==========================================================================
    // ASSET INFO MAP (GetUserAssetInfo/SiteId/{siteId})
    // ==========================================================================
    // Drives the dynamic AttributeName bindings for Point Machine columns
    // that are NOT part of the fixed hardcoded set of 10 operational labels.
    //
    // Response entries are expected to contain:
    //   AssetId, RoleType ('c' = indication / non-datalogger,
    //                      'd' = datalogger),
    //   Role             (use this to match AttributeId from history API
    //                     when RoleType = 'd'),
    //   AssetAttributeId (use this to match AttributeId from history API
    //                     when RoleType = 'c'),
    //   AttributeName    (display label shown in the table header)
    //
    // Backend proxy expected at:
    //   /FRS25/TelemetryHistory/GetUserAssetInfo?siteId={siteId}
    // which should forward to
    //   http://energy7.in:90/api/AssetInfo/GetUserAssetInfo/SiteId/{siteId}
    // ==========================================================================
    var ASSET_INFO_MAP = {};              // assetId -> [{ RoleType, Role, AssetAttributeId, AttributeName, CanonicalName, AliasName }, ...]
    var assetInfoLoaded = false;
    var assetInfoLoadedForSite = null;

    function loadAssetInfoBySite(siteId, callback) {
        if (!siteId || siteId === '' || siteId === '0') {
            ASSET_INFO_MAP = {};
            //assetInfoLoaded = true;
            //assetInfoLoadedForSite = null;
            //if (callback) callback();
            assetInfoLoaded = true;
            assetInfoLoadedForSite = siteId;
            refreshCombinedDLIds();
            if (callback) callback();
            return;
        }

        // Cache: same site, already loaded -> skip
        if (assetInfoLoadedForSite === siteId && assetInfoLoaded) {
            if (callback) callback();
            return;
        }

        $.ajax({
            url: '/FRS25/TelemetryHistory/GetUserAssetInfo?siteId=' + siteId,
            type: 'GET',
            dataType: 'json',
            success: function (response) {
                ASSET_INFO_MAP = {};
                var data = response;
                if (response && !Array.isArray(response)) {
                    data = response.Data || response.data || response.Result || response.result || response;
                }
                if (data && Array.isArray(data) && data.length > 0) {
                    data.forEach(function (item) {
                        if (!item) return;
                        var aId = item.AssetId !== undefined ? item.AssetId : item.assetId;
                        if (aId === undefined || aId === null) return;

                        var roleType = (item.RoleType !== undefined ? item.RoleType : item.roleType);
                        roleType = (roleType || '').toString().toLowerCase().trim();

                        var role = (item.Role !== undefined ? item.Role : item.role);
                        var assetAttrId = (item.AssetAttributeId !== undefined ? item.AssetAttributeId : item.assetAttributeId);
                        var canonicalName = (item.AttributeName !== undefined ? item.AttributeName : item.attributeName) || '';
                        var aliasName = (item.AliasName !== undefined ? item.AliasName : item.aliasName) || '';
                        var channelId = (item.ChannelId !== undefined ? item.ChannelId : item.channelId);
                        channelId = (channelId === null || channelId === undefined) ? '' : channelId.toString().trim();
                        canonicalName = canonicalName.toString().trim();
                        aliasName = aliasName.toString().trim();

                        // Live telemetry orders Signal columns by the canonical Title/AttributeName,
                        // while the History header displays AliasName for normal attributes.
                        // Preserve both values so ordering and display can use the correct source.
                        var attrName = roleType === 'd'
                            ? (canonicalName || aliasName)
                            : (aliasName || canonicalName);

                        var key = String(aId);
                        if (!ASSET_INFO_MAP[key]) ASSET_INFO_MAP[key] = [];
                        ASSET_INFO_MAP[key].push({
                            RoleType: roleType,
                            Role: role,
                            AssetAttributeId: assetAttrId,
                            AttributeName: attrName,
                            CanonicalName: canonicalName || attrName,
                            AliasName: aliasName || attrName,
                            ChannelId: channelId
                        });
                    });
                    console.log('[AssetInfo] Loaded asset info for ' +
                        Object.keys(ASSET_INFO_MAP).length + ' asset(s), siteId=' + siteId);
                }
                assetInfoLoaded = true;
                assetInfoLoadedForSite = siteId;
                refreshCombinedDLIds();
                if (callback) callback();
            },
            error: function (xhr, status, error) {
                console.warn('[AssetInfo] Failed to load GetUserAssetInfo:', status, error);
                ASSET_INFO_MAP = {};
                assetInfoLoaded = true;
                assetInfoLoadedForSite = siteId;
                if (callback) callback();
            }
        });
    }

    // Lookup a single entry for (assetId, attrId, isDataLogger)
    //   isDataLogger = true  -> find RoleType='d' and Role === attrId
    //   isDataLogger = false -> find RoleType='c' and AssetAttributeId === attrId
    function getAssetInfoAttrEntry(assetId, attrId, isDataLogger) {
        if (assetId === undefined || assetId === null) return null;
        var list = ASSET_INFO_MAP[String(assetId)] || ASSET_INFO_MAP[assetId];
        if (!list || list.length === 0) return null;
        var aid = parseInt(attrId, 10);
        if (isNaN(aid)) return null;
        for (var i = 0; i < list.length; i++) {
            var entry = list[i];
            if (!entry) continue;
            if (isDataLogger) {
                if (entry.RoleType === 'd' && parseInt(entry.Role, 10) === aid) return entry;
            } else {
                if (entry.RoleType === 'c' && parseInt(entry.AssetAttributeId, 10) === aid) return entry;
            }
        }
        return null;
    }

    // Get AttributeName for a given (assetId, attrId, isDataLogger).
    // Returns null when no match in ASSET_INFO_MAP -> callers must fall back.
    function getAssetInfoAttrName(assetId, attrId, isDataLogger) {
        var entry = getAssetInfoAttrEntry(assetId, attrId, isDataLogger);
        if (!entry) return null;
        var nm = (entry.AttributeName || '').toString().trim();
        return nm || null;
    }

    function isAttrAllowedForAsset(assetId, attrId, isDataLogger) {
        return true;
    }

    // PM Indication tab: an RDPMS indication column (25/26/576/577/27/28/578/579)
    // is shown only when GetUserAssetInfo lists that AssetAttributeId (RoleType 'c')
    // for the asset with a non-blank ChannelId. Fail-open: an asset with no
    // GetUserAssetInfo entries at all keeps every column.
    function isPmIndicationAttrConfigured(assetId, attrId) {
        var list = (ASSET_INFO_MAP && (ASSET_INFO_MAP[String(assetId)] || ASSET_INFO_MAP[assetId])) || [];
        if (list.length === 0) return true;
        var aid = parseInt(attrId, 10);
        for (var i = 0; i < list.length; i++) {
            var e = list[i];
            if (e && e.RoleType === 'c' && parseInt(e.AssetAttributeId, 10) === aid && e.ChannelId) {
                return true;
            }
        }
        return false;
    }

    // ==========================================================================
    // Datalogger-only assets (Patliputra Track).
    // Some tracks are wired with a DataLogger and no measured attribute at all.
    // The history API still answers with analog attribute ids for them, so the
    // table drew a block of permanently empty attribute columns (plus the seven Track
    // derived columns) beside the one real column. For such an asset only the
    // DataLogger is kept.
    //
    // An analog column that carries even one reading is never hidden, so a plain
    // data gap is untouched. On top of that the asset must look datalogger-only:
    // either GetUserAssetInfo knows it and lists no RoleType 'c' attribute, or
    // the DataLogger itself reported in this range while no analog did.
    // ==========================================================================
    function isHistoryDataloggerOnlyAsset(assetId, attrs, attributeData) {
        if (!attrs || attrs.length === 0) return false;

        var hasDl = false;
        var dlHasData = false;

        for (var i = 0; i < attrs.length; i++) {
            var a = attrs[i];
            if (!a) continue;
            var entries = attributeData ? attributeData[a.compositeKey] : null;
            var count = (entries && entries.length) || 0;

            if (a.isDataLogger) {
                hasDl = true;
                if (count > 0) dlHasData = true;
            } else if (count > 0) {
                return false;   // a real analog reading exists -> normal table
            }
        }
        if (!hasDl) return false;

        var info = (ASSET_INFO_MAP && ASSET_INFO_MAP[String(assetId)]) || [];
        if (info.length > 0) {
            for (var c = 0; c < info.length; c++) {
                // An analog attribute IS configured for this asset; its column is
                // empty only for want of data, so leave the table alone.
                if (info[c] && info[c].RoleType === 'c') return false;
            }
            return true;
        }

        return dlHasData;
    }

    // Load asset attributes from API - stores BOTH Title and AliasName








    // Load asset attributes from API - stores BOTH Title and AliasName
    function loadAssetAttributes(callback) {
        $.ajax({
            url: '/FRS25/TelemetryHistory/GetAssetAttributes',
            type: 'GET',
            dataType: 'json',
            success: function (response) {
                var data = response;
                if (response && !Array.isArray(response)) {
                    data = response.Data || response.data || response.Result || response.result || response;
                }
                if (data && Array.isArray(data) && data.length > 0) {
                    data.forEach(function (item) {
                        var id = item.Id || item.id || item.AttributeId || item.attributeId;
                        var title = item.Title || item.title || item.Name || item.name || item.AttributeName || item.attributeName || '';
                        var alias = item.AliasName || item.aliasName || item.Alias || item.alias || '';

                        if (id !== undefined && id !== null) {
                            // Store both Title and AliasName
                            assetAttributeMap[id] = {
                                title: title,
                                alias: alias || title  // fallback to title if no alias
                            };

                            // Build reverse lookup: title (lowercase) → attrId
                            if (title) {
                                titleToAttrIdMap[title.toLowerCase().trim()] = id;
                            }
                        }
                    });
                    assetAttributeLoaded = true;
                    console.log('[AssetAttr] Loaded ' + Object.keys(assetAttributeMap).length + ' attributes');
                    console.log('[AssetAttr] Sample:', JSON.stringify(assetAttributeMap).substring(0, 500));
                }
                if (callback) callback();
            },
            error: function (xhr, status, error) {
                console.warn('[AssetAttr] Failed to load:', status, error);
                if (callback) callback();
            }
        });
    }

