    //    }
    //    var attr = assetAttributeMap[attrId] || assetAttributeMap[String(attrId)];
    //    if (attr) return attr.alias || attr.title || getPointMachineAttrLabel(attrId) || ('Attr ' + attrId);
    //    return getPointMachineAttrLabel(attrId) || ('Attr ' + attrId);
    //}
    function getAttrDisplayName(attrId, isDataLogger) {
        if (isDataLogger) {
            var dlName = DATALOGGER_RELAY_MAP[attrId] || DATALOGGER_RELAY_MAP[String(attrId)];
            if (dlName) return dlName;
            return null;   // ← unresolved DL — caller will skip
        }
        var attr = assetAttributeMap[attrId] || assetAttributeMap[String(attrId)];
        if (attr) return attr.alias || attr.title || getPointMachineAttrLabel(attrId) || null;
        return getPointMachineAttrLabel(attrId) || null;   // ← unresolved analog — caller will skip
    }
    function getAttrAlias(attrId) {
        var attr = assetAttributeMap[attrId] || assetAttributeMap[String(attrId)];
        if (attr) return attr.alias || attr.title || getPointMachineAttrLabel(attrId) || ('Attr ' + attrId);
        return getPointMachineAttrLabel(attrId) || ('Attr ' + attrId);
    }

    // Get Title for calculations
    function getAttrTitle(attrId) {
        var attr = assetAttributeMap[attrId] || assetAttributeMap[String(attrId)];
        if (attr) return attr.title || attr.alias || getPointMachineAttrLabel(attrId) || ('Attr ' + attrId);
        return getPointMachineAttrLabel(attrId) || ('Attr ' + attrId);
    }

    function formatAliasName(name) {
        if (!name || name.length < 2) return name;
        return name.charAt(0) + '<span class="alias-tc">' + name.substring(1) + '</span>';
    }

    // ==========================================================================
    // DERIVED VALUES CALCULATION - USES TITLE FOR LOOKUP
    // ==========================================================================
    /*
 * Per-asset Track Relay resistance used for VTC TR and RRAIL.
 *
 * Source:
 * FRSAttributeRange rows where AttributeName is
 * "Track Relay resistance".
 *
 * Key   : AssetId
 * Value : AverageValue in Ohms
 *
 * A missing/invalid configured value safely falls back to 10 Ω,
 * matching Telemetry Live.
 */
    var HISTORY_DEFAULT_TRACK_RELAY_RESISTANCE = 10;

    var historyTrackRelayResistanceByAsset = {};
    var historyFRSRangeLoadedSiteId = null;
    var historyFRSRangeLoadingSiteId = null;
    var historyFRSRangeCallbacks = [];



    function normalizeHistoryRangeResponse(response) {
        if ($.isArray(response)) {
            return response;
        }

        if (
            response &&
            $.isArray(response.Data)
        ) {
            return response.Data;
        }

        if (
            response &&
            $.isArray(response.data)
        ) {
            return response.data;
        }

        return [];
    }

    function flushHistoryFRSRangeCallbacks() {
        var callbacks =
            historyFRSRangeCallbacks.slice();

        historyFRSRangeCallbacks = [];

        for (
            var i = 0;
            i < callbacks.length;
            i++
        ) {
            try {
                callbacks[i]();
            } catch (callbackError) {
                console.warn(
                    '[TelemetryHistory][FRSRange] callback failed:',
                    callbackError
                );
            }
        }
    }

    function loadHistoryFRSAttributeRange(
        siteId,
        callback
    ) {
        siteId =
            $.trim(
                String(siteId || '')
            );

        if (typeof callback === 'function') {
            historyFRSRangeCallbacks.push(
                callback
            );
        }

        if (
            !siteId ||
            siteId === '0'
        ) {
            historyTrackRelayResistanceByAsset = {};
            historyFRSRangeLoadedSiteId = null;
            historyFRSRangeLoadingSiteId = null;

            flushHistoryFRSRangeCallbacks();
            return;
        }

        /*
         * Already loaded for this station.
         */
        if (
            String(
                historyFRSRangeLoadedSiteId
            ) === siteId
        ) {
            flushHistoryFRSRangeCallbacks();
            return;
        }

        /*
         * A request for this same station is already running.
         * Its completion will execute the queued callbacks.
         */
        if (
            String(
                historyFRSRangeLoadingSiteId
            ) === siteId
        ) {
            return;
        }

        historyFRSRangeLoadingSiteId =
            siteId;

        $.ajax({
            url:
                '/FRS25/TelemetryHistory/' +
                'GetFRSAttributeRangeBySiteId',

            type: 'GET',
            dataType: 'json',
            cache: false,

            data: {
                siteId: siteId
            },

            success: function (response) {
                var rows =
                    normalizeHistoryRangeResponse(
                        response
                    );

                var resistanceMap = {};

                for (
                    var i = 0;
                    i < rows.length;
                    i++
                ) {
                    var row =
                        rows[i] || {};

                    var attributeName =
                        String(
                            row.AttributeName ||
                            row.attributeName ||
                            ''
                        )
                            .trim()
                            .toLowerCase();

                    if (
                        attributeName !==
                        'track relay resistance'
                    ) {
                        continue;
                    }

                    var assetId =
                        row.AssetId !== undefined
                            ? row.AssetId
                            : row.assetId;

                    if (
                        assetId === null ||
                        assetId === undefined ||
                        String(assetId).trim() === ''
                    ) {
                        continue;
                    }

                    var averageValue =
                        parseFloat(
                            row.AverageValue !== undefined
                                ? row.AverageValue
                                : row.averageValue
                        );

                    /*
                     * Resistance must be positive.
                     * Zero, null, blank and negative values use the 10 Ω fallback.
                     */
                    if (
                        isNaN(averageValue) ||
                        averageValue <= 0
                    ) {
                        continue;
                    }

                    resistanceMap[
                        String(assetId)
                    ] = averageValue;
                }

                historyTrackRelayResistanceByAsset =
                    resistanceMap;

                historyFRSRangeLoadedSiteId =
                    siteId;

                historyFRSRangeLoadingSiteId =
                    null;

                console.log(
                    '[TelemetryHistory][FRSRange] ' +
                    'Track Relay resistance loaded for site ' +
                    siteId +
                    ': ' +
                    Object.keys(resistanceMap).length +
                    ' asset(s)'
                );

                flushHistoryFRSRangeCallbacks();
            },

            error: function (
                xhr,
                status,
                error
            ) {
                historyTrackRelayResistanceByAsset = {};
                historyFRSRangeLoadedSiteId = siteId;
                historyFRSRangeLoadingSiteId = null;

                console.warn(
                    '[TelemetryHistory][FRSRange] ' +
                    'Could not load Track Relay resistance for site ' +
                    siteId +
                    '. Default 10 Ω will be used.',
                    error || status
                );

                /*
                 * History must still render even when the range API fails.
                 */
                flushHistoryFRSRangeCallbacks();
            }
        });
    }

    function getHistoryTrackRelayResistance(
        assetId
    ) {
        var configuredValue =
            parseFloat(
                historyTrackRelayResistanceByAsset[
                String(assetId)
                ]
            );

        if (
            !isNaN(configuredValue) &&
            configuredValue > 0
        ) {
            return configuredValue;
        }

        return HISTORY_DEFAULT_TRACK_RELAY_RESISTANCE;
    }





    var DERIVED_COLUMNS = [
        { id: 'itcBattCharg', name: 'ITC BATT CHARG (mA)', formula: 'Charger mA - If mA' },
        { id: 'vtcVarRes', name: 'VTC VAR RES (V)', formula: 'Charger OP V - Vf - Choke V' },
        { id: 'rtcChFeedEnd', name: 'RTC CH FEED END (Ω)', formula: 'Choke V / If mA × 1000' },
        { id: 'rtcVarRes', name: 'RTC VAR RES (Ω)', formula: 'VTC VAR RES / If mA × 1000' },
        { id: 'vtcTr', name: 'VTC TR (V)', formula: 'Ir mA × TR Res (10Ω)' },
        { id: 'ibalst', name: 'IBALST (mA)', formula: 'If mA - Ir mA' },
        //{ id: 'rrail', name: 'RRAIL (Ω)', formula: '2×(Vf - VTC TR) / (If + Ir) × 1000' }
        { id: 'rrail', name: 'RRAIL (Ω)', formula: '2×(Vf - Vr) / ((If + Ir) / 1000)' }

    ];

        var DERIVED_NAME_ALIASES = {
        ifMa: ['If mA', 'ITC FEED END(mA)', 'ITC FEED END'],
        irMa: ['Ir mA', 'ITC RELAY END(mA)', 'ITC RELAY END'],
        chokeV: ['Choke V', 'VTC CH FEED END(V)', 'VTC CH FEED END'],
        chargerMa: ['Charger mA', 'ITC TFC O/P(mA)', 'ITC TFC O/P'],
        chargerOpV: ['Charger OP V', 'VTC TFC O/P', 'VTC TFC O/P(V)',
            'VTC TFC I/P', 'VTC TFC I/P(V)'],
        vf: ['Vf', 'Vf V', 'VTC FEED END', 'VTC FEED END(V)'],
        vr: ['Vr', 'VTC TR', 'VTC RELAY END', 'VTC RELAY END(V)']
    };

    // Find the compositeKey on this asset whose displayName matches one of
    // the given aliases (case-insensitive). Returns null if nothing matches.
    function _findCompositeKeyByAlias(columns, assetId, aliases) {
        for (var i = 0; i < aliases.length; i++) {
            var want = String(aliases[i]).toLowerCase().trim();
            for (var c = 0; c < columns.length; c++) {
                var col = columns[c];
                if (!col || col.assetId != assetId) continue;
                if (col.isDataLogger) continue;
                if (!col.compositeKey) continue;
                var nm = (col.displayName || '').toLowerCase().trim();
                if (nm === want) return col.compositeKey;
            }
        }
        // Fallback: partial / substring match (handles minor punctuation diffs)
        for (var j = 0; j < aliases.length; j++) {
            var w = String(aliases[j]).toLowerCase().trim();
            for (var d = 0; d < columns.length; d++) {
                var col2 = columns[d];
                if (!col2 || col2.assetId != assetId) continue;
                if (col2.isDataLogger) continue;
                if (!col2.compositeKey) continue;
                var nm2 = (col2.displayName || '').toLowerCase().trim();
                if (nm2 && (nm2.indexOf(w) > -1 || w.indexOf(nm2) > -1)) return col2.compositeKey;
            }
        }
        return null;
    }

    // Find compositeKey by AttrId for this asset (any DataType).
    //function _findCompositeKeyByAttrId(columns, assetId, attrId) {
    //    for (var c = 0; c < columns.length; c++) {
    //        var col = columns[c];
    //        if (!col || col.assetId != assetId) continue;
    //        if (col.isDataLogger) continue;
    //        if (col.attrId === attrId && col.compositeKey) return col.compositeKey;
    //    }
    //    return null;
    //}


    function _findCompositeKeyByAttrId(columns, assetId, attrId) {
        var wantId = Number(attrId);
        for (var c = 0; c < columns.length; c++) {
            var col = columns[c];
            if (!col || col.assetId != assetId) continue;
            if (col.isDataLogger) continue;
            if (Number(col.attrId) === wantId && col.compositeKey) return col.compositeKey;
        }
        return null;
    }

    // Read a numeric value from the per-asset attribute map at a specific row timestamp.
    function _readNumAt(attributeData, ck, rowTs) {
        if (!ck) return null;
        var raw = getValueForTimestamp(attributeData[ck], rowTs);
        if (raw === null || raw === undefined) return null;
        var v = parseFloat(raw);
        return isNaN(v) ? null : v;
    }

    // Drop-in replacement: works without assetAttributeMap.
    //function calculateDerivedForRow(attributeData, columns, assetId, rowTs) {
    //    // ── Resolve sensor compositeKeys for THIS asset ──────────────────
    //    // First four: stable AttrIds (matches live page constants).
    //    var ckIfMa = _findCompositeKeyByAttrId(columns, assetId, 1);
    //    var ckIrMa = _findCompositeKeyByAttrId(columns, assetId, 2);
    //    var ckChokeV = _findCompositeKeyByAttrId(columns, assetId, 4);
    //    var ckChargerMa = _findCompositeKeyByAttrId(columns, assetId, 5);
    function calculateDerivedForRow(attributeData, columns, assetId, rowTs) {
        // \u2500\u2500 Resolve sensor compositeKeys for THIS asset \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
        // First four: stable AttrIds (matches live page constants), falling back
        // to name-alias matching (same mechanism the raw columns already use)
        // if this asset/data source doesn't expose that AttrId.
        var ckIfMa = _findCompositeKeyByAttrId(columns, assetId, 1)
            || _findCompositeKeyByAlias(columns, assetId, DERIVED_NAME_ALIASES.ifMa);
        var ckIrMa = _findCompositeKeyByAttrId(columns, assetId, 2)
            || _findCompositeKeyByAlias(columns, assetId, DERIVED_NAME_ALIASES.irMa);
        var ckChokeV = _findCompositeKeyByAttrId(columns, assetId, 4)
            || _findCompositeKeyByAlias(columns, assetId, DERIVED_NAME_ALIASES.chokeV);
        var ckChargerMa = _findCompositeKeyByAttrId(columns, assetId, 5)
            || _findCompositeKeyByAlias(columns, assetId, DERIVED_NAME_ALIASES.chargerMa);

        // Last two: resolved by AliasName.
        var ckChargerOpV =
            _findCompositeKeyByAlias(
                columns,
                assetId,
                DERIVED_NAME_ALIASES.chargerOpV
            );

        var ckVf =
            _findCompositeKeyByAlias(
                columns,
                assetId,
                DERIVED_NAME_ALIASES.vf
            );

        // ── Read values at this timestamp ────────────────────────────────
        var ifMa =
            _readNumAt(
                attributeData,
                ckIfMa,
                rowTs
            );

        var irMa =
            _readNumAt(
                attributeData,
                ckIrMa,
                rowTs
            );

        var chokeV =
            _readNumAt(
                attributeData,
                ckChokeV,
                rowTs
            );

        var chargerMa =
            _readNumAt(
                attributeData,
                ckChargerMa,
                rowTs
            );

        var chargerOpV =
            _readNumAt(
                attributeData,
                ckChargerOpV,
                rowTs
            );

        var vf =
            _readNumAt(
                attributeData,
                ckVf,
                rowTs
            );

        // ── Compute using the same Track formulas as Telemetry Live ──────
        var derived = {};

        /*
         * Use the configured Track Relay resistance for this asset.
         * If configuration is absent or invalid, the helper returns 10 Ω.
         */
        var trackRelayResistance =
            getHistoryTrackRelayResistance(
                assetId
            );

        // 1. ITC BATT CHARG (mA) = Charger mA − If mA
        derived.itcBattCharg =
            (
                chargerMa !== null &&
                ifMa !== null
            )
                ? chargerMa - ifMa
                : null;

        // 2. VTC VAR RES (V) = Charger OP V − Vf − Choke V
        derived.vtcVarRes =
            (
                chargerOpV !== null &&
                vf !== null &&
                chokeV !== null
            )
                ? chargerOpV - vf - chokeV
                : null;

        // 3. RTC CH FEED END (Ω) = Choke V / If mA × 1000
        derived.rtcChFeedEnd =
            (
                chokeV !== null &&
                ifMa !== null &&
                ifMa !== 0
            )
                ? (
                    chokeV /
                    ifMa
                ) * 1000
                : null;

        // 4. RTC VAR RES (Ω) = VTC VAR RES / If mA × 1000
        derived.rtcVarRes =
            (
                derived.vtcVarRes !== null &&
                ifMa !== null &&
                ifMa !== 0
            )
                ? (
                    derived.vtcVarRes /
                    ifMa
                ) * 1000
                : null;

        // 5. VTC TR (V) = Ir mA × Track Relay Resistance / 1000
        derived.vtcTr =
            irMa !== null
                ? (
                    irMa *
                    trackRelayResistance
                ) / 1000
                : null;

        // 6. IBALST (mA) = If mA − Ir mA
        derived.ibalst =
            (
                ifMa !== null &&
                irMa !== null
            )
                ? ifMa - irMa
                : null;

        // 7. RRAIL (Ω)
        // Same formula used in Telemetry Live:
        //
        // RRAIL = 2 × (Vf − VTC TR) / ((If + Ir) / 1000)
        var ifPlusIr =
            (
                ifMa !== null &&
                irMa !== null
            )
                ? ifMa + irMa
                : null;

        derived.rrail =
            (
                vf !== null &&
                derived.vtcTr !== null &&
                ifPlusIr !== null &&
                ifPlusIr !== 0
            )
                ? (
                    2 *
                    (
                        vf -
                        derived.vtcTr
                    )
                ) /
                (
                    ifPlusIr /
                    1000
                )
                : null;

        // A calculated value <= 0 shows as 0, EXCEPT ITC BATT CHARG, which
        // keeps its sign (negative = battery supplying, not charging).
        // Runs after every formula so dependent formulas use the real value.
        _clampDerivedNonPositive(derived);

        return derived;
    }

    function _clampDerivedNonPositive(d) {
        Object.keys(d).forEach(function (k) {
            if (k === 'itcBattCharg') { return; }
            if (d[k] !== null && d[k] !== undefined && !isNaN(d[k]) && d[k] <= 0) { d[k] = 0; }
        });
        return d;
    }

    // Kept for any legacy callers — same semantics, but if you can switch
    // them to call calculateDerivedForRow directly that's preferable.
    function calculateDerivedValues(attrValues) {
        // attrValues here is name-keyed (legacy). We rebuild what we need
        // via case-insensitive lookups so the old call sites still work.
        function pick(names) {
            for (var i = 0; i < names.length; i++) {
                for (var k in attrValues) {
                    if (k && k.toLowerCase().trim() === names[i].toLowerCase().trim()) {
                        var v = parseFloat(attrValues[k]);
                        if (!isNaN(v)) return v;
                    }
                }
            }
            return null;
        }
        var ifMa = pick(['If mA', 'ITC FEED END(mA)', 'ITC FEED END']);
        var irMa = pick(['Ir mA', 'ITC RELAY END(mA)', 'ITC RELAY END']);
        var chokeV = pick(['Choke V', 'VTC CH FEED END(V)', 'VTC CH FEED END']);
        var chargerMa = pick(['Charger mA', 'ITC TFC O/P(mA)', 'ITC TFC O/P']);
        var chargerOpV =
            pick(
                DERIVED_NAME_ALIASES.chargerOpV
            );

        var vf =
            pick(
                DERIVED_NAME_ALIASES.vf
            );

        /*
         * Legacy method does not receive assetId.
         * Use the same safe fallback used by Telemetry Live when
         * an asset-specific resistance cannot be resolved.
         */
        var trackRelayResistance =
            HISTORY_DEFAULT_TRACK_RELAY_RESISTANCE;

        var d = {};

        d.itcBattCharg =
            (
                chargerMa !== null &&
                ifMa !== null
            )
                ? chargerMa - ifMa
                : null;

        d.vtcVarRes =
            (
                chargerOpV !== null &&
                vf !== null &&
                chokeV !== null
            )
                ? chargerOpV - vf - chokeV
                : null;

        d.rtcChFeedEnd =
            (
                chokeV !== null &&
                ifMa !== null &&
                ifMa !== 0
            )
                ? (
                    chokeV /
                    ifMa
                ) * 1000
                : null;

        d.rtcVarRes =
            (
                d.vtcVarRes !== null &&
                ifMa !== null &&
                ifMa !== 0
            )
                ? (
                    d.vtcVarRes /
                    ifMa
                ) * 1000
                : null;

        d.vtcTr =
            irMa !== null
                ? (
                    irMa *
                    trackRelayResistance
                ) / 1000
                : null;

        d.ibalst =
            (
                ifMa !== null &&
                irMa !== null
            )
                ? ifMa - irMa
                : null;

        var ifPlusIr =
            (
                ifMa !== null &&
                irMa !== null
            )
                ? ifMa + irMa
                : null;

        d.rrail =
            (
                vf !== null &&
                d.vtcTr !== null &&
                ifPlusIr !== null &&
                ifPlusIr !== 0
            )
                ? (
                    2 *
                    (
                        vf -
                        d.vtcTr
                    )
                ) /
                (
                    ifPlusIr /
                    1000
                )
                : null;

        return _clampDerivedNonPositive(d);
    }
    function formatDerivedValue(val) {
        if (val === null || val === undefined || isNaN(val)) return '0.00';
        if (Math.abs(val) >= 100) return val.toFixed(1);
        return val.toFixed(2);
    }

    function getDerivedHeadersHtml(themeColor) {
        var h = '';
        DERIVED_COLUMNS.forEach(function (col) {
            h += '<th class="derived-col" style="background:' + themeColor + ';" title="' + col.formula + '">';
            h += formatAliasName(col.name);
            h += '</th>';
        });
        return h;
    }

    function getDerivedCellsHtml(derived) {
        var h = '';
        h += '<td class="derived-val">' + formatDerivedValue(derived.itcBattCharg) + '</td>';
        h += '<td class="derived-val">' + formatDerivedValue(derived.vtcVarRes) + '</td>';
        h += '<td class="derived-val">' + formatDerivedValue(derived.rtcChFeedEnd) + '</td>';
        h += '<td class="derived-val">' + formatDerivedValue(derived.rtcVarRes) + '</td>';
        h += '<td class="derived-val">' + formatDerivedValue(derived.vtcTr) + '</td>';
        h += '<td class="derived-val">' + formatDerivedValue(derived.ibalst) + '</td>';
        h += '<td class="derived-val">' + formatDerivedValue(derived.rrail) + '</td>';
        return h;
    }

    function isTrackAssetType() {
        var assetTypeId = $('#drpAssetType').val();
        return assetTypeId === '1' || assetTypeId === 1;
    }

    /*
     * Do not depend on a hardcoded IPS AssetTypeId.
     * IPS IDs may differ between databases/sites.
     */
        function isIpsHistoryAssetType() {
        var assetTypeName = $.trim(
            $('#drpAssetType option:selected').text() || ''
        ).toUpperCase();

        return assetTypeName === 'IPS' ||
            assetTypeName.indexOf('IPS ') === 0 ||
            assetTypeName.indexOf(' IPS') > -1;
    }

    function isEldHistoryAssetType() {
        var assetTypeId =
            parseInt(
                $('#drpAssetType').val(),
                10
            ) || 0;

        var assetTypeName = $.trim(
            $('#drpAssetType option:selected').text() || ''
        ).toUpperCase();

        return assetTypeId === 31 ||
            assetTypeName === 'ELD' ||
            assetTypeName.indexOf('ELD ') === 0 ||
            assetTypeName.indexOf(' ELD') > -1;
    }

    function supportsHistoryStackedGraph() {
        return isIpsHistoryAssetType() ||
            isEldHistoryAssetType();
    }


    // ======================================================================
    // TRACK / SIGNAL ORDER — kept in parity with telemetrylive.js
    // ======================================================================
    // Track uses the explicit AttributeId sequence first (the same authority
    // used by Live), then falls back to the canonical attribute-name sequence.
    var HISTORY_TRACK_ID_SEQUENCE = [344, 569, 5, 249, 1, 4, 3, 2, 570, 6, 571];
    var HISTORY_TRACK_COLUMN_SEQUENCE = [
        'If mA',
        'Ir mA',
        'Vr',
        'Choke V',
        'Charger mA',
        'TPR V',
        'Vf',
        'Charger V',
        'Charger OP V',
        'TPR V (Loc)',
        'TR V (Relay)'
    ];

    // Signal uses canonical AttributeName/Title values, matching _signalColSeq
    // in telemetrylive.js. AliasName remains the displayed table header.
    var HISTORY_SIGNAL_COLUMN_SEQUENCE = [
        'RG mA', 'RG V',
        'DG mA', 'DG V',
        'HG mA', 'HG V',
        'HHG mA', 'HHG V',
        'PILOT mA', 'PILOT V', 'PILOTRoot mA', 'PILOTRoot V',
        'Co_Hg mA', 'Co_Hg V',
        'Root mA', 'Root V',
        'AUG mA', 'AUG V', 'BUG mA', 'BUG V', 'CUG mA', 'CUG V',
        'DUG mA', 'DUG V', 'EUG mA', 'EUG V',
        'On Aspect mA', 'On Aspect V', 'Off Aspect mA', 'Off Aspect V',
        'DPR', 'HPR', 'HHPR',
        'Sh-HPR'
    ];

    function normalizeHistorySequenceName(value) {
        // Ignore case and harmless separator differences while preserving the
        // semantic text (e.g. TPR V versus TPR V (Loc)).
        return (value || '').toString().toUpperCase().replace(/[^A-Z0-9]+/g, '');
    }

    function getHistorySequenceIndex(value, sequence) {
        var normalized = normalizeHistorySequenceName(value);
        if (!normalized) return -1;
        for (var i = 0; i < sequence.length; i++) {
            if (normalized === normalizeHistorySequenceName(sequence[i])) return i;
        }
        return -1;
    }

    function getHistoryCanonicalAttrName(assetId, attrId, isDataLogger, fallbackName) {
        var info = getAssetInfoAttrEntry(assetId, attrId, isDataLogger);
        if (info) {
            var canonical = (info.CanonicalName || '').toString().trim();
            if (canonical) return canonical;
        }

        // Fallback for deployments where GetUserAssetInfo does not expose the
        // canonical name but GetAssetAttributes has populated the title map.
        if (!isDataLogger) {
            var attr = assetAttributeMap[attrId] || assetAttributeMap[String(attrId)];
            if (attr && attr.title) return attr.title;
        }

        return (fallbackName || '').toString().trim();
    }

    function getHistoryTrackColumnRank(column, fallbackAssetId) {
        var attrId = parseInt(column && column.attrId, 10);
        var idRank = HISTORY_TRACK_ID_SEQUENCE.indexOf(attrId);
        if (idRank >= 0) return idRank;

        var assetId = column && column.assetId !== undefined ? column.assetId : fallbackAssetId;
        var canonicalName = getHistoryCanonicalAttrName(
            assetId,
            column ? column.attrId : null,
            !!(column && column.isDataLogger),
            column ? column.displayName : ''
        );
        var nameRank = getHistorySequenceIndex(canonicalName, HISTORY_TRACK_COLUMN_SEQUENCE);
        if (nameRank < 0 && column) {
            nameRank = getHistorySequenceIndex(column.displayName, HISTORY_TRACK_COLUMN_SEQUENCE);
        }
        return nameRank >= 0 ? 100 + nameRank : 10000;
    }

    function getHistorySignalColumnRank(column, fallbackAssetId) {
        var assetId = column && column.assetId !== undefined ? column.assetId : fallbackAssetId;
        var canonicalName = getHistoryCanonicalAttrName(
            assetId,
            column ? column.attrId : null,
            !!(column && column.isDataLogger),
            column ? column.displayName : ''
        );
        var rank = getHistorySequenceIndex(canonicalName, HISTORY_SIGNAL_COLUMN_SEQUENCE);
        if (rank < 0 && column) {
            rank = getHistorySequenceIndex(column.displayName, HISTORY_SIGNAL_COLUMN_SEQUENCE);
        }
        return rank >= 0 ? rank : 10000;
    }

    function compareHistoryAttributeColumns(a, b, assetTypeId, fallbackAssetId) {
        var aIsDL = !!(a && a.isDataLogger);
        var bIsDL = !!(b && b.isDataLogger);

        // Same behavior as History already had, and as Live presents it:
        // normal telemetry first, DataLogger at the end of each asset block.
        if (aIsDL !== bIsDL) return aIsDL ? 1 : -1;

        var typeId = parseInt(assetTypeId, 10);
        var aRank = 10000;
        var bRank = 10000;

        if (!aIsDL && typeId === 1) {
            aRank = getHistoryTrackColumnRank(a, fallbackAssetId);
            bRank = getHistoryTrackColumnRank(b, fallbackAssetId);
        } else if (!aIsDL && typeId === 2) {
            aRank = getHistorySignalColumnRank(a, fallbackAssetId);
            bRank = getHistorySignalColumnRank(b, fallbackAssetId);
        }

        if (aRank !== bRank) return aRank - bRank;

        var aId = parseInt(a && a.attrId, 10);
        var bId = parseInt(b && b.attrId, 10);
        if (!isNaN(aId) || !isNaN(bId)) {
            if (isNaN(aId)) aId = 999999;
            if (isNaN(bId)) bId = 999999;
            if (aId !== bId) return aId - bId;
        }

        return ((a && a.displayName) || '').localeCompare(
            ((b && b.displayName) || ''),
            undefined,
            { numeric: true, sensitivity: 'base' }
        );
    }

    function compareHistoryAssetNames(a, b) {
        return ((a && (a.assetName || a.Name)) || '').localeCompare(
            ((b && (b.assetName || b.Name)) || ''),
            undefined,
            { numeric: true, sensitivity: 'base' }
        );
    }

    function sortHistoryAssetResultsLikeLive(assetResults) {
        if (!assetResults || assetResults.length < 2) return assetResults || [];
        var typeId = parseInt($('#drpAssetType').val(), 10);
        if (typeId !== 1 && typeId !== 2) return assetResults;
        return assetResults.slice().sort(compareHistoryAssetNames);
    }
