    // Scans ASSET_INFO_MAP for entries where RoleType='d' and AttributeName
    // starts with "Combined-" (e.g. Combined-NWCR, Combined-RWCR, Combined-NWKR,
    // Combined-RWKR). Returns an array of Role values (as integers) which are
    // the AttributeIds in the telemetry history API.

    // Get combined DL IDs for a specific asset
        function getCombinedDLIdsForAsset(assetId) {
    var assetKey = String(assetId);
    var list =
        DATALOGGER_ASSET_MAP[assetKey] || [];

    var ids = [];

    for (var i = 0; i < list.length; i++) {
        var item = list[i];

        if (!item) continue;

        var name = (
            item.DataloggerAttribute || ''
        ).toString().trim().toLowerCase();

        /*if (name.indexOf('combined') === 0) {*/
        // Some devices label these relays with the abbreviated "Co-" prefix
        // (e.g. "Co-HR", "Co-HECR") instead of "Combined-". Both forms are
        // the same kind of combined relay DataLogger attribute and must be
        // treated identically -- otherwise they're excluded from
        // PM_COMBINED_DATALOGGER_IDS and silently dropped from the
        // Indication tab (row-timestamp gate at ~line 15307 whitelists on
        // this exact list).
        //if (name.indexOf('combined') === 0 || name.indexOf('co-') === 0) {
        //    var dataloggerAttributeId =
        //        parseInt(
        //            item.DataloggerAttributeId,
        //            10
        //        );

        //    if (
        //        !isNaN(dataloggerAttributeId) &&
        //        ids.indexOf(
        //            dataloggerAttributeId
        //        ) === -1
        //    ) {
        //        ids.push(
        //            dataloggerAttributeId
        //        );
        //    }
        //}

        if (name.indexOf('combined') === 0 || name.indexOf('co-') === 0) {
            /*
             * The telemetry history API identifies DataLogger attributes by
             * Role, NOT by DataloggerAttributeId. Every consumer of this list
             * compares it against an incoming telemetry attrId, and those are
             * matched to config via RoleType==='d' && Role === attrId (see
             * ~line 7171, ~15890, ~19199).
             *
             * PM_COMBINED_DATALOGGER_IDS_FALLBACK = [225,226,221,222] is also
             * a list of Role values, so pushing DataloggerAttributeId here
             * replaced a correct Role list with one that can never match --
             * e.g. asset 41895 Co-HR is Role 414 / DataloggerAttributeId 270,
             * so the column was dropped.
             *
             * Role is pushed first (the real match). DataloggerAttributeId is
             * still pushed afterwards so anything that already keyed on it --
             * including the Integration-API shape built at ~line 7300, where
             * DataloggerAttributeId already holds the telemetry id -- keeps
             * working unchanged.
             */
            var roleAttributeId =
                parseInt(
                    item.Role,
                    10
                );

            if (
                !isNaN(roleAttributeId) &&
                ids.indexOf(
                    roleAttributeId
                ) === -1
            ) {
                ids.push(
                    roleAttributeId
                );
            }

            var dataloggerAttributeId =
                parseInt(
                    item.DataloggerAttributeId,
                    10
                );

            if (
                !isNaN(dataloggerAttributeId) &&
                ids.indexOf(
                    dataloggerAttributeId
                ) === -1
            ) {
                ids.push(
                    dataloggerAttributeId
                );
            }
        }
    }

        return ids;
    }

    /*
     * Asset-scoped DataLogger name lookup.
     *
     * DATALOGGER_RELAY_MAP is global and keyed by DataloggerAttributeId, but
     * telemetry columns arrive keyed by Role, so "Co-HR" (DataloggerAttributeId
     * 270 / Role 414) never resolved and getAttrDisplayName returned null.
     *
     * Role keys are deliberately NOT merged into the global map: they collide.
     * In live config Role 291 / 292 (OFFECR / ONECR) are also
     * DataloggerAttributeId 291 / 292 (ELD POINT / ELD DAC UP), so a global
     * merge would mislabel those columns. Scoping the lookup to one asset
     * removes the ambiguity.
     *
     * Returns null when unresolved so every existing caller's fallback chain
     * behaves exactly as before.
     */
    function getDataloggerNameForAsset(assetId, attrId) {
        var list =
            (typeof DATALOGGER_ASSET_MAP !== 'undefined' &&
                DATALOGGER_ASSET_MAP[String(assetId)]) || [];

        var key = String(attrId);

        for (var i = 0; i < list.length; i++) {
            var item = list[i];

            if (!item) {
                continue;
            }

            if (
                String(item.Role) === key ||
                String(item.DataloggerAttributeId) === key ||
                String(item.HistoryAttributeId) === key
            ) {
                return item.DataloggerAttribute || null;
            }
        }

        return null;
    }

    // Get ALL combined DL IDs across all assets in ASSET_INFO_MAP

    // Get ALL combined DL IDs across all assets in ASSET_INFO_MAP
    function getAllCombinedDLIds() {
        var ids = [];
        for (var assetId in ASSET_INFO_MAP) {
            if (!ASSET_INFO_MAP.hasOwnProperty(assetId)) continue;
            var assetIds = getCombinedDLIdsForAsset(assetId);
            for (var j = 0; j < assetIds.length; j++) {
                if (ids.indexOf(assetIds[j]) === -1) ids.push(assetIds[j]);
            }
        }
        // Fallback to hardcoded IDs if nothing found from API
        if (ids.length === 0) return PM_COMBINED_DATALOGGER_IDS_FALLBACK.slice();
        return ids;
    }

    // Refresh PM_COMBINED_DATALOGGER_IDS from ASSET_INFO_MAP (call after loadAssetInfoBySite)
    function refreshCombinedDLIds() {
        var dynamic = getAllCombinedDLIds();
        PM_COMBINED_DATALOGGER_IDS = dynamic;
        PM_OPERATIONAL_DL_IDS = dynamic;
        console.log('[CombinedDL] Dynamic IDs:', JSON.stringify(dynamic));
    }

