    // ── Build ordered columns per asset, matching exact Excel column sequence ──
    // Loops over each assetGroup and builds the colOrder for EACH asset separately,
    // so multiple assets each get their own complete set of ordered columns.
    //
    // LABEL RESOLUTION:
    //   - def.fixedLabel === true  -> use def.label verbatim (hardcoded)
    //   - def.fixedLabel === false -> look up AttributeName via GetUserAssetInfo
    //                                 (RoleType + Role/AssetAttributeId match against
    //                                  the history API's AttributeId), fall back to
    //                                 def.label if the API has no matching entry.
    function buildPMOrderedColumns(rawColumns, colOrder, firstAssetId, assetGroups) {
        if (!assetGroups || assetGroups.length === 0) {
            assetGroups = [{ assetId: firstAssetId, assetName: (typeof assetNameMap !== 'undefined' && assetNameMap && assetNameMap[firstAssetId]) ? assetNameMap[firstAssetId] : ('Asset ' + firstAssetId) }];
        }

        // Identify which view is being built (by colOrder identity)
        var isOpView = (colOrder === PM_OP_COL_ORDER);
        var isIndView = !isOpView;
        var combinedDlIds = (typeof PM_COMBINED_DATALOGGER_IDS !== 'undefined')
            ? PM_COMBINED_DATALOGGER_IDS
            : [225, 226, 221, 222];

        var ordered = [];
        assetGroups.forEach(function (group) {
            var aId = group.assetId;
            var aName = group.assetName;
            var _isHalfPM = (typeof window._pmAssetIsHalf === 'function') && window._pmAssetIsHalf(aId);
            var assetRaw = rawColumns.filter(function (c) { return c.assetId === aId; });

            // ---- (1) Curated entries from colOrder ---------------------------
            // For PM Operational view, Normal-side Op event columns (1002 / 2002 /
            // 1005 / 3002 / 4002 / 3005) share their cell with the corresponding
            // Reverse-side attrId (6002 / 7002 / 6005 / 8002 / 9002 / 8005). The
            // renderer treats `missing:true` as "force a '-' cell", so if we only
            // check for the Normal attrId's presence in assetRaw, an asset that
            // only reports Reverse data (e.g. PPTA-PT-64 A-End) will render '-'
            // even though parseTableData's reverse-fallback lookup can resolve
            // the value. Fix: also count the column as present when the Reverse
            // counterpart is in assetRaw.
            var _pmNormalToReverse = {
                1002: 6002, 2002: 7002, 1005: 6005,
                3002: 8002, 4002: 9002, 3005: 8005
            };
            var emittedKeys = {}; // track (attrId + isDataLogger) already emitted
            colOrder.forEach(function (def) {
                if (_isHalfPM && def.group === 'B') { return; }   // half PM: End A only
                // Indication view: only attrs configured with a channel in GetUserAssetInfo
                if (isIndView && !def.isDataLogger && !isPmIndicationAttrConfigured(aId, def.attrId)) { return; }
                var match = null;
                for (var i = 0; i < assetRaw.length; i++) {
                    var c = assetRaw[i];
                    if (c.attrId === def.attrId && c.isDataLogger === def.isDataLogger) {
                        match = c;
                        break;
                    }
                }

                // Op view: if the Normal attrId isn't in assetRaw, check whether
                // the Reverse counterpart is. If so, we DON'T want the renderer
                // to short-circuit the cell to '-' — the reverse-fallback lookup
                // in parseTableData can fill it. We record this as
                // `hasReverseCounterpart`; missing stays false but compositeKey
                // stays null so the render path takes the reverse-fallback
                // branch (which correctly sets _resolvedIsReverse=true and picks
                // the right waveform direction).
                var _hasReverseCounterpart = false;
                if (!match && isOpView && !def.isDataLogger && _pmNormalToReverse[def.attrId]) {
                    var _revId = _pmNormalToReverse[def.attrId];
                    for (var j = 0; j < assetRaw.length; j++) {
                        var _rc = assetRaw[j];
                        if (_rc.attrId === _revId && !_rc.isDataLogger) {
                            _hasReverseCounterpart = true;
                            break;
                        }
                    }
                }

                var resolvedName;
                if (def.fixedLabel === true) {
                    resolvedName = def.label;
                } else {
                    var apiName = getAssetInfoAttrName(aId, def.attrId, def.isDataLogger);
                    resolvedName = apiName || def.label;
                }

                ordered.push({
                    attrId: def.attrId,
                    compositeKey: match ? match.compositeKey : null,
                    isDataLogger: def.isDataLogger,
                    displayName: resolvedName,
                    assetId: aId,
                    assetName: aName,
                    group: def.group || null,
                    missing: !match && !_hasReverseCounterpart
                });
                emittedKeys[def.attrId + '_' + (def.isDataLogger ? 'd' : 'c')] = true;
            });

            // ---- (2) INDICATION view: append only combined DL relay columns ---
            // These columns were previously appended to the Operational tab.
            // Requirement: when Point Machine is selected, Combined-NWKR/RWKR/NWCR/RWCR
            // DataLogger columns must be hidden from Operational and shown in Indication.
            //if (isIndView) {
            //    var dlRaw = assetRaw
            //        .filter(function (c) {
            //            var dlAttrId = parseInt(c.attrId, 10);
            //            return c.isDataLogger
            //                && combinedDlIds.indexOf(dlAttrId) !== -1
            //                && !emittedKeys[c.attrId + '_d']
            //                && isAttrAllowedForAsset(aId, c.attrId, true);
            //        })
            //        .sort(function (a, b) {
            //            var ai = combinedDlIds.indexOf(parseInt(a.attrId, 10));
            //            var bi = combinedDlIds.indexOf(parseInt(b.attrId, 10));
            if (isIndView) {
                // Use per-asset combined DL IDs from ASSET_INFO_MAP (dynamic),
                // falling back to global list for backwards compatibility.
                var perAssetDlIds = getCombinedDLIdsForAsset(aId);
                var effectiveDlIds = (perAssetDlIds.length > 0) ? perAssetDlIds : combinedDlIds;
                //console.log('[PM-IndDL] Asset ' + aId + ': perAssetDlIds=' + JSON.stringify(perAssetDlIds) + ', effectiveDlIds=' + JSON.stringify(effectiveDlIds));
                //console.log('[PM-IndDL] Asset ' + aId + ': assetRaw DL columns=' + JSON.stringify(assetRaw.filter(function (c) { return c.isDataLogger; }).map(function (c) { return { attrId: c.attrId, ck: c.compositeKey }; })));
                // PERFORMANCE: removed [PM-IndDL] per-asset debug logs (JSON.stringify over asset columns for every asset render).
                var dlRaw = assetRaw
                    .filter(function (c) {
                        // Trust the Integration API: it returns exactly the Combined
                        // DataLogger columns for this tab (Combined-NWKR/RWKR/NWCR/RWCR
                        // -- 267/268/282/283 per README). Bind every DataLogger column
                        // it returns instead of gating on a hardcoded/dynamic id list
                        // that can miss the real ids and hide the DataLogger half of
                        // the Indication & Datalogger tab. effectiveDlIds is still used
                        // for ordering in the sort below.
                        return c.isDataLogger
                            && !emittedKeys[c.attrId + '_d']
                            && isAttrAllowedForAsset(aId, c.attrId, true);
                    })
                    .sort(function (a, b) {
                        var ai = effectiveDlIds.indexOf(parseInt(a.attrId, 10));
                        var bi = effectiveDlIds.indexOf(parseInt(b.attrId, 10));
                        if (ai === -1) ai = 999;
                        if (bi === -1) bi = 999;
                        return (ai - bi) || (a.attrId - b.attrId);
                    });

                //console.log('[PM-IndDL] Asset ' + aId + ': matched dlRaw count=' + dlRaw.length);
                // PERFORMANCE: removed [PM-IndDL] matched dlRaw count log.

                dlRaw.forEach(function (c) {
                    var dataloggerAlias = getDataloggerNameForAsset(
                        aId,
                        c.attrId
                    ) || getAttrDisplayName(
                        c.attrId,
                        true
                    );

var apiName = getAssetInfoAttrName(
    aId,
    c.attrId,
    true
);

var resolvedName =
    dataloggerAlias ||
    apiName ||
    POINT_MACHINE_DISPLAY_NAMES[c.attrId] ||
    ('DL-' + c.attrId);

//console.log(
//    '[PM-IndDL] Appending DL col:',
//    {
//        assetId: aId,
//        attrId: c.attrId,
//        dataloggerAlias: dataloggerAlias,
//        apiName: apiName,
//        resolvedName: resolvedName
//    }
                    //);

                    // PERFORMANCE: removed [PM-IndDL] Appending DL col log — ran per DL column per asset.
                    ordered.push({
                        attrId: c.attrId,
                        compositeKey: c.compositeKey,
                        isDataLogger: true,
                        //displayName: apiName || POINT_MACHINE_DISPLAY_NAMES[c.attrId] || ('DL-' + c.attrId),
                        displayName: resolvedName,
                        assetId: aId,
                        assetName: aName,
                        group: 'DL',
                        missing: false
                    });
                });
            }
        });
        return ordered;
    }

    function setPmView(mode) {
        var _prevMode = pmViewMode;
        pmViewMode = mode;

        // A Point Machine tab is a data-source selector, not an indicator of
        // whether the currently selected source has records.  Keep every tab
        // available so an empty Operation response does not prevent users
        // from opening Indication & Datalogger or Vibration.
        $('#pmViewToggle').css('display', 'flex');
        $('#btnPmOperational').toggleClass('active', mode === 'operational');
        $('#btnPmIndication').toggleClass('active', mode === 'indication');
        $('#btnPmVibration').toggleClass('active', mode === 'vibration');

      // For Point Machine, each tab uses a different backend API:
        //   Operational  → DashboardPMHistoryOperation
        //   Indication   → DashboardPMHistoryIntegration
        //   Vibration    → DashboardHistory (generic)
        // Re-trigger the search when switching so the correct API is called.
        if (_prevMode !== mode) {
            var _pmModeCheck = ($('#drpAssetType option:selected').text() || '').trim().toUpperCase();
            if (
                (_pmModeCheck === 'POINT MACHINE' || _pmModeCheck === 'POINT_MACHINE') &&
                typeof fnSearchHistory === 'function'
            ) {
                // Filters changed since the last Search: keep the tab choice
                // but do not search for the new filters without a Search click.
                if (_thBlockIfSearchRequired()) return;
                // Reset the previous tab's DOM + caches + server-paging
                // state BEFORE firing the new tab's search so:
                //  (a) the user immediately sees the loader over an
                //      empty area rather than the previous tab's rows
                //      lingering until the first new response lands;
                //  (b) any in-flight page-N callback from the previous
                //      tab (via _dashLoadServerPage) bails on its !st
                //      guard instead of writing old-tab data into
                //      shared state (lastAssetResults etc.);
                //  (c) thPageSizes / thCaches / thCurrentPages don't
                //      carry across tabs, since column shape, row
                //      count, and page semantics differ per endpoint.
                // clearHistoryView() hides #pmViewToggle -- re-show it
                // because we're still on Point Machine, just switching
                // sub-view (button active state was set above and is
                // untouched by clearHistoryView).
                // Keep the previous tab's results so the view can be restored
                // if the new tab's search cannot run (validation bail) --
                // otherwise switching tabs just blanks the page.
                var _pmPrevResults = (typeof lastAssetResults !== 'undefined' && lastAssetResults)
                    ? lastAssetResults
                    : null;

                clearHistoryView();
                $('#pmViewToggle').css('display', 'flex');

                var _pmSearchRan = fnSearchHistory();
                if (_pmSearchRan === false) {
                    // Search never fired -> put the previous view back and stay
                    // on the tab the user actually had data for.
                    pmViewMode = _prevMode;
                    $('#btnPmOperational').toggleClass('active', _prevMode === 'operational');
                    $('#btnPmIndication').toggleClass('active', _prevMode === 'indication');
                    $('#btnPmVibration').toggleClass('active', _prevMode === 'vibration');
                    if (_pmPrevResults) {
                        lastAssetResults = _pmPrevResults;
                        renderHistoryTable(_pmPrevResults);
                    }
                }
                return;
            }
        }

        if (lastAssetResults) renderHistoryTable(lastAssetResults);
    }

    function filterColumnsForAssetType(columns, assetType) {
        if (assetType !== 'POINT MACHINE') return columns;
        // Just return as-is — PM ordering is handled in parseTableData PM filter block
        return columns;
    }
