        // Which ends carry a vibration sensor, straight from GetUserAssetInfo
        // (ASSET_INFO_MAP). Each attribute's AttributeName ends with "-A end" /
        // "-B end", so a vibration attribute on an end proves the sensor is there.
        //   in map + vibration attr(s)   -> { a/b as found, known:true }
        //   in map + NO vibration attr   -> { a:false, b:false, known:true } (no sensor -> table suppressed)
        //   NOT in map (unknown)         -> null (caller falls back)
        // Which ends carry a vibration sensor for one asset, read ONLY from
        // GetUserAssetInfo (ASSET_INFO_MAP). Self-contained: the vibration-name
        // test and the -A end / -B end suffix test are inline, so this cannot
        // silently fail because a helper defined later is out of scope.
        //   in map + vibration attr(s) -> { a/b as found }
        //   in map + NO vibration attr -> { a:false, b:false }  (no sensor)
        //   NOT in map (unknown)       -> null                  (caller falls back)
        function _vibEndsFromAssetInfo(assetId) {
            var list = (typeof ASSET_INFO_MAP !== 'undefined' && ASSET_INFO_MAP)
                ? (ASSET_INFO_MAP[String(assetId)] || ASSET_INFO_MAP[assetId] || [])
                : [];
            if (!list.length) { return null; }
            var a = false, b = false;
            for (var i = 0; i < list.length; i++) {
                var it = list[i];
                var nm = String((it && (it.CanonicalName || it.AttributeName || it.AliasName)) || '');
                if (!nm) { continue; }
                var low = nm.toLowerCase();
                var isVib = low.indexOf('vibration') !== -1 || low.indexOf('accel') !== -1 ||
                    /\bvib\b/.test(low) || /full\s*band/.test(low) ||
                    /\bhf\s*rms\b/.test(low) || /pk[\s\-_]*pk/.test(low);
                if (!isVib) { continue; }
                // Strip synthetic suffixes, then read the trailing -A end / -B end.
                var raw = nm.trim().replace(/-(Max|Avg|Array|Min|Count|OperationTime)$/i, '');
                if (/(?:^|[\s_-])A[\s_-]*END(?:[\s_-]*A[\s_-]*END)?$/i.test(raw)) { a = true; }
                else if (/(?:^|[\s_-])B[\s_-]*END(?:[\s_-]*B[\s_-]*END)?$/i.test(raw)) { b = true; }
            }
            return { a: a, b: b };
        }

        // Exported: fnSearchHistory lives in the OUTER script scope and cannot
        // see these closure-scoped declarations without an explicit window handle.
        window._vibEndsFromAssetInfo = _vibEndsFromAssetInfo;

        // True when this asset has a vibration sensor on EITHER end. Drives which
        // assets the vibration tab requests at all.
        function _vibAssetHasSensor(assetId) {
            // GetAssestBy wins when it answered for this asset.
            var flags = _vibEndsFromAssetFlags(assetId);
            if (flags) { return !!(flags.a || flags.b); }

            var e = _vibEndsFromAssetInfo(assetId);
            if (!e) { return true; }   // unknown -> fail open, still request
            return !!(e.a || e.b);
        }
