            // VibrationA / VibrationB from GetAssestBy is authoritative.
            // strict:true tells _vibBuildAssetTable not to widen these ends
            // with whatever data happens to be on the page.
            var flags = _vibEndsFromAssetFlags(assetId);
            if (flags) {
                return {
                    a: flags.a,
                    b: flags.b,
                    any: (flags.a || flags.b),
                    known: true,
                    strict: true
                };
            }

            var info = _vibEndsFromAssetInfo(assetId);
            if (!info) { return { a: true, b: true, any: true, known: false, strict: false }; }
