        // ===== MULTI-SELECT HELPERS =====
        function getDropdownTrigger(id) {
            return $('.select-btn[data-target="' + id + '"]')[0] || null;
        }

    function positionFilterDropdown(id, btn) {
        var $dd = $('#' + id);

        if (!$dd.length || !btn) {
            return;
        }

        var rect = btn.getBoundingClientRect();
        var docEl = document.documentElement;
        var viewportWidth =
            docEl.clientWidth ||
            window.innerWidth ||
            0;

        var viewportHeight =
            docEl.clientHeight ||
            window.innerHeight ||
            0;

        var margin = 8;
        var gap = 4;
        var availableWidth = Math.max(
            1,
            viewportWidth - (margin * 2)
        );

        var preferredMinWidth =
            id === 'ddViewType' ? 180 : 260;

        var preferredMaxWidth =
            id === 'ddViewType' ? 220 : 320;

        var dropdownWidth = Math.max(
            rect.width,
            preferredMinWidth
        );

        dropdownWidth = Math.min(
            dropdownWidth,
            preferredMaxWidth,
            availableWidth
        );

        $dd.css({
            width: Math.round(dropdownWidth) + 'px',
            minWidth: Math.round(dropdownWidth) + 'px',
            maxWidth: Math.round(dropdownWidth) + 'px'
        });

        var $list = $dd.find('.ms-dropdown-list');
        $list.css('max-height', '');

        var naturalHeight = $dd.outerHeight();
        var spaceBelow =
            viewportHeight -
            rect.bottom -
            gap -
            margin;

        var spaceAbove =
            rect.top -
            gap -
            margin;

        var openAbove =
            naturalHeight > spaceBelow &&
            spaceAbove > spaceBelow;

        var usableHeight = Math.max(
            48,
            openAbove ? spaceAbove : spaceBelow
        );

        if ($list.length && naturalHeight > usableHeight) {
            var listHeight = $list.outerHeight();
            var fixedHeight = naturalHeight - listHeight;

            var responsiveListHeight = Math.max(
                48,
                Math.min(
                    250,
                    usableHeight - fixedHeight
                )
            );

            $list.css(
                'max-height',
                Math.round(responsiveListHeight) + 'px'
            );
        }

        var dropdownHeight = $dd.outerHeight();

        var top = openAbove
            ? rect.top - gap - dropdownHeight
            : rect.bottom + gap;

        var left = rect.left;

        top = Math.max(
            margin,
            Math.min(
                top,
                viewportHeight - dropdownHeight - margin
            )
        );

        left = Math.max(
            margin,
            Math.min(
                left,
                viewportWidth - dropdownWidth - margin
            )
        );

        $dd.css({
            top: Math.round(top) + 'px',
            left: Math.round(left) + 'px'
        });
    }

    function repositionOpenDropdown() {
        if (!openDropdown) {
            return;
        }

        var btn = getDropdownTrigger(openDropdown);

        if (!btn) {
            closeDD();
            return;
        }

        positionFilterDropdown(openDropdown, btn);
    }

    function handleDropdownViewportScroll(event) {
        var target = event ? event.target : null;

        if (
            target &&
            target.nodeType === 1 &&
            $(target).closest('.filter-dropdown').length
        ) {
            return;
        }

        scheduleDropdownReposition();
    }

    var dropdownPositionFrame = null;

    function scheduleDropdownReposition() {
        if (
            !openDropdown ||
            dropdownPositionFrame !== null
        ) {
            return;
        }

        var schedule =
            window.requestAnimationFrame ||
            function (callback) {
                return window.setTimeout(callback, 16);
            };

        dropdownPositionFrame = schedule(function () {
            dropdownPositionFrame = null;
            repositionOpenDropdown();
        });
    }

    function toggleDD(id, btn) {
        if (openDropdown === id) {
            closeDD();
            return;
        }

        closeDD();

        var $dd = $('#' + id);

        $dd
            .css('visibility', 'hidden')
            .addClass('open');

        positionFilterDropdown(id, btn);

        $dd.css('visibility', 'visible');

        $(btn).addClass('active');
        $('#backdrop').addClass('show');
        openDropdown = id;

        setTimeout(function () {
            var $search =
                $dd.find('.ms-dropdown-search input');

            if ($search.length) {
                $search.focus();
            }
        }, 100);
    }

    function closeDD() {
        if (openDropdown) {
            var $dd = $('#' + openDropdown);

            $dd
                .find('.ms-dropdown-search input')
                .val('');

            $dd
                .find(
                    '.ms-dropdown-item, ' +
                    '.ms-dropdown-item-single'
                )
                .removeClass('hidden');

            $dd
                .find('.ms-dropdown-no-results')
                .removeClass('show');

            $dd
                .find('.ms-dropdown-item')
                .each(function () {
                    var origText = $(this).data('text');

                    if (origText) {
                        $(this)
                            .find('span')
                            .text(origText);
                    }
                });

            $dd
                .removeClass('open')
                .css('visibility', '');

            $dd
                .find('.ms-dropdown-list')
                .css('max-height', '');

            $('.select-btn').removeClass('active');
            $('#backdrop').removeClass('show');
            openDropdown = null;
        }
    }

    function msSelectAll(type, checked) {
        var listId = (type === 'site') ? 'listSite' : 'listAsset';
        $('#' + listId + ' .ms-dropdown-item').each(function () {
            $(this).find('.cb-' + type).prop('checked', checked);
            $(this).toggleClass('checked', checked);
        });
        msUpdateText(type);
    }

    function msUpdateSelectAllState(type) {
        var listId = (type === 'site') ? 'listSite' : 'listAsset';
        var chkAllId = (type === 'site') ? 'chkAllSite' : 'chkAllAsset';
        var $allItems = $('#' + listId + ' .ms-dropdown-item');
        var totalAll = $allItems.length;
        var checkedAll = $allItems.find('.cb-' + type + ':checked').length;
        $('#' + chkAllId).prop('checked', totalAll > 0 && totalAll === checkedAll);
    }

    function msUpdateText(type) {
        var listId =
            type === 'site'
                ? 'listSite'
                : 'listAsset';

        var $all =
            $('#' + listId + ' .ms-dropdown-item .cb-' + type);

        var $checked =
            $all.filter(':checked');

        var total =
            $all.length;

        var count =
            $checked.length;

        var text;

        if (count === 0) {
            /*
             * IPS:
             * no checked asset means All Assets.
             *
             * Other asset types keep the previous Select behaviour.
             */
            text =
                type === 'asset' &&
                    isIpsHistoryAssetType() &&
                    total > 0
                    ? 'All'
                    : 'Select';
        }
        else if (count === total) {
            text = 'All';
        }
        else if (count === 1) {
            text =
                $checked
                    .first()
                    .closest('.ms-dropdown-item')
                    .data('text') ||

                $checked
                    .first()
                    .closest('.ms-dropdown-item')
                    .find('span')
                    .text();
        }
        else {
            text =
                count + ' selected';
        }

        var txtId =
            type === 'site'
                ? 'txtSite'
                : 'txtAsset';

        $('#' + txtId).text(text);

        msUpdateSelectAllState(type);

        if (type === 'asset') {
            updateGraphOptionState();
        }
    }

    function msGetValues(type) {
        var vals = [];
        $('.cb-' + type + ':checked').each(function () {
            var v = $(this).val();
            if (v) { vals.push(v); }
            // Grouped items (see the batt charging/discharging dropdown builder)
            // carry additional asset ids in data-extra-ids so the primary value
            // remains a normal single id for every other consumer. Fan them out
            // here so the caller receives every underlying asset id.
            var extra = $(this).attr('data-extra-ids');
            if (extra) {
                var parts = extra.split(',');
                for (var _pi = 0; _pi < parts.length; _pi++) {
                    if (parts[_pi]) { vals.push(parts[_pi]); }
                }
            }
        });
        return vals;
    }
    function updateGraphOptionState() {
        var count =
            msGetValues('asset').length;

        var $graphItem =
            $('#ddViewType .ms-dropdown-item-single[data-value="Graph"]');

        /*
         * IPS and ELD Graph support:
         *   0 selected = All Assets (IPS)
         *   1 selected = Single Asset
         *   N selected = Multiple Assets (Stacked lanes by default)
         */
        if (supportsHistoryStackedGraph()) {
            $graphItem.removeClass('disabled');
            return;
        }

        /*
         * Preserve existing restriction for non-IPS / non-ELD asset types.
         */
        if (count > 1) {
            $graphItem.addClass('disabled');

            if (selectedViewType === 'Graph') {
                selectedViewType = 'Table';

                $('#txtViewType')
                    .text('Table');

                $('#ddViewType .ms-dropdown-item-single')
                    .removeClass('checked');

                $('#ddViewType .ms-dropdown-item-single[data-value="Table"]')
                    .addClass('checked');

                if (
                    lastAssetResults &&
                    lastAssetResults.length > 0
                ) {
                    renderByViewType(
                        lastAssetResults
                    );

                    /*
                     * This switch to Table is programmatic (selecting >1 asset
                     * disables Graph), so the view-type click handler never
                     * runs. A table has just been rendered, so the report
                     * button belongs back on screen.
                     */
                    syncDownloadVisibility();
                }
            }
        }
        else {
            $graphItem.removeClass('disabled');
        }
    }

    function filterMsDropdown(type, searchText) {
        var ddId = (type === 'site') ? 'ddSite' : 'ddAsset';
        var $dropdown = $('#' + ddId);
        var $items = $dropdown.find('.ms-dropdown-item');
        var $noResults = $dropdown.find('.ms-dropdown-no-results');
        var search = searchText.toLowerCase().trim();
        var visibleCount = 0;

        $items.each(function () {
            var $item = $(this);
            var text = ($item.data('text') || $item.find('span').text()).toLowerCase();
            if (search === '' || text.indexOf(search) > -1) {
                $item.removeClass('hidden');
                visibleCount++;
                if (search !== '') {
                    var originalText = $item.data('text') || $item.find('span').text();
                    var regex = new RegExp('(' + escapeRegex(searchText) + ')', 'gi');
                    $item.find('span').html(originalText.replace(regex, '<mark>$1</mark>'));
                } else {
                    var origText = $item.data('text');
                    if (origText) $item.find('span').text(origText);
                }
            } else {
                $item.addClass('hidden');
            }
        });
        $noResults.toggleClass('show', visibleCount === 0 && search !== '');
    }

    function escapeRegex(string) { return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

    // ===== DATE HELPERS =====
    function formatDateForInput(date) {
        var y = date.getFullYear();
        var m = ('0' + (date.getMonth() + 1)).slice(-2);
        var d = ('0' + date.getDate()).slice(-2);
        return y + '-' + m + '-' + d;
    }

    function formatTimeForInput(date) {
        return ('0' + date.getHours()).slice(-2) + ':' + ('0' + date.getMinutes()).slice(-2);
    }

    function formatDateTimeForAPI(dateStr, timeStr, secStr) {
        if (!dateStr) return '';
        var parts = dateStr.split('-');
        var timeParts = (timeStr || '00:00').split(':');
    //    return parts[2] + parts[1] + parts[0] + '_' + ('0' + timeParts[0]).slice(-2) + ('0' + timeParts[1]).slice(-2) + ('0' + new Date().getSeconds()).slice(-2);
        return parts[2] + parts[1] + parts[0] + '_' + ('0' + timeParts[0]).slice(-2) + ('0' + timeParts[1]).slice(-2) + ('0' + (timeParts[2] || secStr || '0')).slice(-2);    }

    // ===== FUTURE DATE / TIME GUARD =========================================
    // The native max="" attribute on <input type="date"> only blocks future
    // days inside the calendar popup, and <input type="time"> has no notion of
    // "today" at all -- so a user can still pick today's date with a future
    // hour/minute and search a window that has not happened yet. These helpers
    // clamp the pickers back to "now" and are re-used by fnSearchHistory() as a
    // final gate, so neither typing, pasting nor a programmatic change can send
    // a future startDate/endDate upstream.

    // type="date" returns YYYY-MM-DD; legacy pickers may return DD-MM-YYYY.
    function _thNormalizeDateStr(dateStr) {
        var s = String(dateStr || '');
        if (s.charAt(2) === '-') {
            var p = s.split('-');
            return p[2] + '-' + p[1] + '-' + p[0];
        }
        return s;
    }

    // Local Date for a picker pair. secStr fills the seconds an <input
    // type="time"> never supplies ('0' for the window start, '59' for its end).
    function _thPickerDate(dateStr, timeStr, secStr) {
        var s = _thNormalizeDateStr(dateStr);
        if (!s) return null;
        var t = String(timeStr || '00:00').split(':');
        var d = new Date(
            s + 'T' +
            ('0' + (t[0] || '00')).slice(-2) + ':' +
            ('0' + (t[1] || '00')).slice(-2) + ':' +
            ('0' + (t[2] || secStr || '0')).slice(-2)
        );
        return isNaN(d.getTime()) ? null : d;
    }

    function _thIsToday(dateStr) {
        return _thNormalizeDateStr(dateStr) === formatDateForInput(new Date());
    }

    // Keeps a time picker's max in sync with the date beside it: a "today"
    // date caps the time at the current HH:mm, any earlier date allows 23:59.
    function _thSyncTimeMax($dateInput, $timeInput) {
        if (!$timeInput || !$timeInput.length) return;
        if (_thIsToday($dateInput.val())) {
            $timeInput.attr('max', formatTimeForInput(new Date()));
        } else {
            $timeInput.removeAttr('max');
        }
    }

    // Clamps a date+time pair back to the current date/time. Returns true when
    // a clamp actually happened.
    function _thClampDateTimeToNow($dateInput, $timeInput, label) {
        if (!$dateInput || !$dateInput.length) return false;

        var now = new Date();
        var todayValue = formatDateForInput(now);
        var changed = false;

        // --- day ---
        var dateVal = _thNormalizeDateStr($dateInput.val());
        if (dateVal && dateVal > todayValue) {   // yyyy-mm-dd compares correctly as string
            $dateInput.val(todayValue);
            dateVal = todayValue;
            changed = true;
            showWarning(
                'Future date is not allowed. ' + label + ' Date has been set to today.',
                'Invalid Date'
            );
        }

        _thSyncTimeMax($dateInput, $timeInput);

        // --- hour / minute (only meaningful once the day IS today) ---
        if ($timeInput && $timeInput.length && dateVal === todayValue) {
            var timeVal = String($timeInput.val() || '');
            if (timeVal) {
                var nowTime = formatTimeForInput(now);        // HH:mm
                // HH:mm compares correctly as a zero-padded string.
                if (timeVal.slice(0, 5) > nowTime) {
                    $timeInput.val(nowTime);
                    changed = true;
                    showWarning(
                        'Future time is not allowed. ' + label + ' Time has been set to the current time (' + nowTime + ').',
                        'Invalid Time'
                    );
                }
            }
        }

        return changed;
    }

    function formatTimestamp(date) {
        var dd = ('0' + date.getDate()).slice(-2);
        var mm = ('0' + (date.getMonth() + 1)).slice(-2);
        var yyyy = date.getFullYear();
        var hh = ('0' + date.getHours()).slice(-2);
        var mi = ('0' + date.getMinutes()).slice(-2);
        var ss = ('0' + date.getSeconds()).slice(-2);
        return dd + '/' + mm + '/' + yyyy + ' ' + hh + ':' + mi + ':' + ss;
    }
    function formatTimestampWithBadge(date) {
        var s = formatTimestamp(date);
        if (date && date._isStartRow) {
            return '<div style="display:flex;flex-direction:column;align-items:flex-start;gap:2px;line-height:1.1;">' +
                '<span>' + s + '</span>' +
                '<span class="last-updated-badge" style="display:inline-block;background:#fef3c7;color:#92400e;border:1px solid #fcd34d;border-radius:3px;padding:1px 6px;font-size:9px;font-weight:600;letter-spacing:.3px;white-space:nowrap;">' +
                '<i class="fas fa-clock-rotate-left" style="font-size:8px;margin-right:3px;"></i>Last Updated</span>' +
                '</div>';
        }
        return s;
    }

    function formatTimestampShort(date) {
        return ('0' + date.getDate()).slice(-2) + '/' + ('0' + (date.getMonth() + 1)).slice(-2) + ' ' + ('0' + date.getHours()).slice(-2) + ':' + ('0' + date.getMinutes()).slice(-2);
    }

    function formatDateDDMMYYYY(date) {
        var day = String(date.getDate()).padStart(2, '0');
        var month = String(date.getMonth() + 1).padStart(2, '0');
        var year = date.getFullYear();
        return day + '/' + month + '/' + year;
    }

    function formatDateTimeDDMMYYYY(date) {
        var day = String(date.getDate()).padStart(2, '0');
        var month = String(date.getMonth() + 1).padStart(2, '0');
        var year = date.getFullYear();
        var hours = date.getHours();
        var minutes = String(date.getMinutes()).padStart(2, '0');
        var seconds = String(date.getSeconds()).padStart(2, '0');
        var ampm = hours >= 12 ? 'PM' : 'AM';
        hours = hours % 12; hours = hours ? hours : 12;
        return day + '/' + month + '/' + year + ', ' + String(hours).padStart(2, '0') + ':' + minutes + ':' + seconds + ' ' + ampm;
    }

    function convertDateToddmmyyyy(dateStr) {
        if (!dateStr) return '';
        var parts = dateStr.split('-');
        if (parts.length === 3) return parts[2] + '/' + parts[1] + '/' + parts[0];
        return dateStr;
    }
    function GetDivisionByZone(zoneId) {
        /*
         * Zone changed:
         * clear every dependent selection before loading divisions.
         * This prevents divisions/sites/assets from the previous zone
         * remaining visible.
         */
        $('#drpDivisions')
            .empty()
            .append('<option value="">Select</option>');

        $('#drpSite')
            .empty()
            .append('<option value="">Select division first</option>');

        $('#listAsset').html(
            '<div class="ms-dropdown-empty">' +
            'Select Station &amp; Asset Type first' +
            '</div>'
        );

        $('#chkAllAsset').prop('checked', false);
        $('#txtAsset').text('Select');

        zoneId = $.trim(String(zoneId || ''));

        /*
         * Zone cleared:
         * retain the existing empty dependent-dropdown behaviour.
         */
        if (!zoneId || zoneId === '0') {
            return;
        }

        /*
         * Use the same DivisionLister request structure and the same
         * MVC controller method used by Telemetry Live.
         */
        var requestData = {
            SearchCriteria: {
                ZoneIds: [
                    parseInt(zoneId, 10)
                ]
            }
        };

        $("#loader").show();

        $.ajax({
            url:
                '/FRS25/Telemetry/GetDivisionByZoneId',

            type: 'POST',

            data:
                JSON.stringify(requestData),

            contentType:
                'application/json; charset=utf-8',

            dataType:
                'json',

            success: function (response) {
                $("#loader").hide();

                /*
                 * Support direct arrays as well as wrapped MVC responses.
                 */
                var divisions =
                    Array.isArray(response)
                        ? response
                        : (
                            response &&
                                Array.isArray(response.Data)
                                ? response.Data
                                : (
                                    response &&
                                        Array.isArray(response.data)
                                        ? response.data
                                        : []
                                )
                        );

                $('#drpDivisions')
                    .empty()
                    .append(
                        '<option value="">Select</option>'
                    );

                $.each(
                    divisions,
                    function (index, division) {
                        if (
                            !division ||
                            division.Id === null ||
                            division.Id === undefined
                        ) {
                            return;
                        }

                        $('#drpDivisions').append(
                            $('<option></option>')
                                .val(division.Id)
                                .text(division.Name || '')
                        );
                    }
                );
            },

            error: function (
                xhr,
                status,
                error
            ) {
                $("#loader").hide();

                $('#drpDivisions')
                    .empty()
                    .append(
                        '<option value="">Select</option>'
                    );

                console.error(
                    '[Telemetry History Division] Failed:',
                    {
                        zoneId: zoneId,
                        status: xhr
                            ? xhr.status
                            : status,
                        error: error,
                        responseText: xhr
                            ? xhr.responseText
                            : ''
                    }
                );

                showError(
                    'Failed to load divisions.',
                    'Error'
                );
            }
        });
    }
