    function GetSitesByDivision(divisionId) {
        $('#listAsset').html('<div class="ms-dropdown-empty">Select Station &amp; Asset Type first</div>');
        $('#chkAllAsset').prop('checked', false);
        $('#txtAsset').text('Select');

        if (!divisionId || divisionId === '0') {
            // Division cleared. If a Zone is still selected, keep Station empty
            // and prompt user — otherwise show generic "Select".
            var zoneId = $('#drpZones').val();
            if (zoneId && zoneId !== '0' && zoneId !== '') {
                $('#drpSite').empty().append('<option value="">Select division first</option>');
            } else {
                $('#drpSite').empty().append('<option value="">Select</option>');
            }
            return;
        }

        // Division selected — clear and load only stations for this division.
        $('#drpSite').empty().append('<option value="">Select</option>');

        $("#loader").show();
        $.ajax({
            url: '/FRS25/TelemetryHistory/GetSiteByDivisionId',
            type: 'GET',
            data: { divisionId: divisionId },
            success: function (data) {
                $("#loader").hide();
                if (data && data.length > 0) {
                    $.each(data, function (key, value) {
                        $('#drpSite').append('<option value="' + value.Id + '">' + value.Name + '</option>');
                    });
                }
            },
            error: function () { $("#loader").hide(); showError('Failed to load sites.', 'Error'); }
        });
    }

       /*
 * Asset Number loading is triggered after the current
 * Asset Type selection is completed.
 */


    function debounceAssetNumbers() {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(loadAssetNumbers, 50);
    }
    function loadAssetNumbers() {
        var siteId = $('#drpSite').val();
        var assetTypeId = $('#drpAssetType').val();

        $('#listAsset').html('<div class="ms-dropdown-empty">Select Station &amp; Asset Type first</div>');
        $('#chkAllAsset').prop('checked', false);
        $('#txtAsset').text('All');
        // Reset whitelist when (site, asset type) changes — same as live (line 8410).
        validAssetIds = [];

        if (!siteId || siteId === '0' || siteId === '' || !assetTypeId || assetTypeId === '0' || assetTypeId === '') return;

        $('#listAsset').html('<div class="ms-dropdown-empty">Loading...</div>');

        $.ajax({
            url: '/FRS25/TelemetryHistory/GetAssestBy',
            type: 'GET',
            data: { siteId: siteId, assetTypeId: assetTypeId },
            success: function (data) {
                // VibrationA / VibrationB per asset ride on this same payload.
                if (typeof window.setPmVibrationAssetFlags === 'function') {
                    window.setPmVibrationAssetFlags(data);
                }
                if (typeof window.setPmHalfPointFlags === 'function') {
                    window.setPmHalfPointFlags(data);
                }

                if (data && data.length > 0) {

            // Natural name order (T2 before T10), matching Telemetry Live rows.

                    data.sort(compareHistoryAssetNames);
                    var html = '';
                    // Rebuild whitelist (string IDs for safe comparison — same as live line 8426).
                 validAssetIds = [];

                    PM_TRACK_MAP = {};
                    _vibResetTrackCauseCache();

                    // Collapse BATT CHARGING 1/2/... and BATT DISCHARGING 1/2/...
                    // into a single dropdown item each. The item's primary
                    // data-value / checkbox value stays a SINGLE asset id (the
                    // first of the group) so every existing consumer that reads
                    // one id per row keeps working. The rest of the group's ids
                    // live in data-extra-ids and are fanned out only inside
                    // msGetValues, which is the single point that turns the
                    // dropdown state into the search's asset list.
                    var _ddGroupMap = {};   // baseName -> { first:{...}, extras:[ids] }
                    var _ddOrdered = [];    // render order

                    for (var i = 0; i < data.length; i++) {
                        validAssetIds.push(String(data[i].Id));
                        _vibCapturePointTrackMapping(data[i]);

                        var _bucket = (typeof _ipsChargingBucket === 'function')
                            ? _ipsChargingBucket(data[i].Name) : null;

                        if (_bucket) {
                            var _base = (typeof _ipsChargingBaseName === 'function')
                                ? _ipsChargingBaseName(data[i].Name)
                                : data[i].Name;
                            if (!_ddGroupMap[_base]) {
                                _ddGroupMap[_base] = { first: data[i], extras: [], baseName: _base };
                                _ddOrdered.push({ grouped: true, key: _base });
                            } else {
                                _ddGroupMap[_base].extras.push(String(data[i].Id));
                            }
                        } else {
                            _ddOrdered.push({ grouped: false, asset: data[i] });
                        }
                    }

                    for (var _oi = 0; _oi < _ddOrdered.length; _oi++) {
                        var _od = _ddOrdered[_oi];
                        if (_od.grouped) {
                            var _grp = _ddGroupMap[_od.key];
                            // Primary id = the first group member. Extra ids are
                            // stashed on data-extra-ids for msGetValues to expand.
                            var _extraAttr = _grp.extras.length
                                ? ' data-extra-ids="' + _grp.extras.join(',') + '"'
                                : '';
                            html +=
                                '<div class="ms-dropdown-item checked ms-dropdown-item-group" ' +
                                'data-value="' + _grp.first.Id + '" ' +
                                'data-text="' + _grp.baseName + '"' + _extraAttr + '>' +
                                '<input type="checkbox" class="cb-asset" ' +
                                'value="' + _grp.first.Id + '"' + _extraAttr + ' checked>' +
                                '<span>' + _grp.baseName + '</span>' +
                                '</div>';
                        } else {
                            var _a = _od.asset;
                            html +=
                                '<div class="ms-dropdown-item checked" ' +
                                'data-value="' + _a.Id + '" ' +
                                'data-text="' + _a.Name + '">' +
                                '<input type="checkbox" class="cb-asset" ' +
                                'value="' + _a.Id + '" checked>' +
                                '<span>' + _a.Name + '</span>' +
                                '</div>';
                        }
                    }

                    $('#listAsset').html(html);

                    /*
                     * Header checked because every individual asset is selected by default.
                     * Button text reflects the all-selected state.
                     */
                    $('#chkAllAsset').prop('checked', true);
                    msUpdateText('asset');

                    updateGraphOptionState();                        // button reads "All" since count === total
                    if (window.updateSelInfoBar) setTimeout(window.updateSelInfoBar, 0);
                    console.log(
                        '[Assets] Whitelist populated: ' +
                        validAssetIds.length +
                        ' assets. No selection represents All Assets.' +
                        ' site=' + siteId +
                        ', type=' + assetTypeId
                    );
                } else {
                    validAssetIds = [];
                    $('#chkAllAsset').prop('checked', false);
                    $('#txtAsset').text('Select');
                    $('#listAsset').html('<div class="ms-dropdown-empty">No assets found</div>');
                }
            },
            error: function () {
                validAssetIds = [];
                if (typeof window.resetPmVibrationAssetFlags === 'function') {
                    window.resetPmVibrationAssetFlags();
                }
                $('#listAsset').html('<div class="ms-dropdown-empty">Error loading assets</div>');
            }
        });
    }
