        return '<div class="pm-vh-wrap">' +
            '<div class="pm-vh-head"><h6>' +
            '<span class="pm-vh-title-icon"><i class="fas fa-wave-square"></i></span>' +
            _vibEsc(nm) + ' \u2014 Vibration Data' +
            '</h6></div>' +
            '<div class="pm-vh-empty">' +
            (spin ? '<i class="fas fa-spinner fa-spin"></i>' : '<i class="fas fa-wave-square"></i>') +
            '<span>' + _vibEsc(message) + '</span>' +
            '</div></div>';
