        if (/\(\s*Ω\s*\)/.test(name) || /\bohm\b/i.test(name)) return 'Ω';
        if (/\(\s*mA\s*\)/i.test(name)) return 'mA';
        if (/\(\s*V\s*\)/i.test(name)) return 'V';

