    //                        assetName: (typeof assetNameMap !== 'undefined' && assetNameMap[assetId]) ? assetNameMap[assetId] : ('Asset ' + assetId),
    //                        attributes: attrs,
    //                        pageTimestamps: allTs.filter(Boolean),
    //                        serverPaging: true,
    //                        operationApi: useOp, indicationApi: useInd, vibrationApi: useVib
    //                    });
